chat-app.css:
/* Modern Chat Container */
.chat-app {
    display: flex;
    flex-direction: column;
    height: 100vh;
    background: var(--dark-900);
}

chat-header.css:
/* Professional Header */
.chat-header {
    height: 60px;
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--glass-border);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 24px;
    box-shadow: var(--glass-shadow);
    position: relative;
}

model-selector.css:
.model-selector {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--dark-700);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 8px 16px;
    cursor: pointer;
    transition: all 0.3s ease;
}



.model-selector:hover {
    background: var(--dark-600);
    border-color: var(--accent-blue);
}

model-indicator.css:
.model-indicator {
    width: 8px;
    height: 8px;
    background: var(--accent-green);
    border-radius: 50%;
    animation: pulse-dot 2s infinite;
}

system-status.css:
.system-status {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 12px;
    color: var(--light-400);
}

status-indicator.css:
.status-indicator {
    width: 6px;
    height: 6px;
    background: var(--accent-green);
    border-radius: 50%;
    display: inline-block;
    margin-right: 4px;
}

settings-btn.css:
.settings-btn {
    width: 36px;
    height: 36px;
    border: none;
    background: var(--dark-700);
    color: var(--light-300);
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
}



.settings-btn:hover {
    background: var(--dark-600);
    color: var(--accent-blue);
}

header-badge.css:
.header-badge {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
    padding: 6px 12px;
    border-radius: 16px;
    font-size: 12px;
    font-weight: 600;
}

chat-messages.css:
/* Chat Messages Area */
.chat-messages {
    flex: 1;
    padding: 24px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 24px;
    background: linear-gradient(180deg, var(--dark-900) 0%, var(--dark-950) 100%);
    position: relative;
}



    .chat-messages {
        padding: 16px;
    }

welcome-screen.css:
/* Welcome Screen */
.welcome-screen {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    flex: 1;
    text-align: center;
    max-width: 700px;
    margin: 0 auto;
}

welcome-icon.css:
.welcome-icon {
    width: 120px;
    height: 120px;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 32px;
    font-size: 48px;
    color: white;
    animation: gentle-glow 3s ease-in-out infinite;
}

welcome-greeting.css:
.welcome-greeting {
    font-size: 42px;
    font-weight: 700;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: 16px;
}



    .welcome-greeting {
        font-size: 32px;
    }

welcome-subtitle.css:
.welcome-subtitle {
    font-size: 18px;
    color: var(--light-400);
    line-height: 1.6;
    margin-bottom: 40px;
}



    .welcome-subtitle {
        font-size: 16px;
    }

recent-activity.css:
/* Recent Activity Section */
.recent-activity {
    width: 100%;
    max-width: 600px;
    margin-top: 32px;
}

recent-header.css:
.recent-header {
    font-size: 16px;
    font-weight: 600;
    color: var(--light-200);
    margin-bottom: 16px;
    display: flex;
    align-items: center;
    gap: 8px;
}

quick-launch-grid.css:
.quick-launch-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 12px;
    margin-bottom: 24px;
}



    .quick-launch-grid {
        grid-template-columns: 1fr 1fr;
    }

quick-launch-card.css:
.quick-launch-card {
    background: var(--glass-bg);
    backdrop-filter: blur(10px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 16px;
    cursor: pointer;
    transition: all 0.3s ease;
}



.quick-launch-card:hover {
    background: rgba(59, 130, 246, 0.1);
    border-color: var(--accent-blue);
    transform: translateY(-2px);
}

card-icon.css:
.card-icon {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 8px;
    font-size: 14px;
}

floating-nav.css:
/* Floating Bubble Navigation */
.floating-nav {
    position: fixed;
    right: 24px;
    top: 50%;
    transform: translateY(-50%);
    display: flex;
    flex-direction: column;
    gap: 16px;
    z-index: 1000;
}


    .floating-nav {
        right: 16px;
        gap: 12px;
    }

nav-bubble.css:
.nav-bubble {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    border: 1px solid var(--glass-border);
    backdrop-filter: blur(20px);
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.3s ease;
    position: relative;
    font-size: 20px;
}



.nav-bubble:hover {
    transform: scale(1.1);
    box-shadow: 0 8px 32px rgba(59, 130, 246, 0.3);
}



.nav-bubble.artifacts {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
}



.nav-bubble.projects {
    background: linear-gradient(135deg, var(--accent-green), var(--accent-cyan));
    color: white;
}



.nav-bubble.training {
    background: linear-gradient(135deg, var(--accent-yellow), var(--accent-red));
    color: white;
}



.nav-bubble.git {
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-blue));
    color: white;
}



.nav-bubble.research {
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-green));
    color: white;
}



.nav-bubble:hover .bubble-popover {
    opacity: 1;
    visibility: visible;
    transform: translateY(-50%) translateX(-8px);
}



    .nav-bubble {
        width: 48px;
        height: 48px;
        font-size: 18px;
    }

artifacts.css:
.nav-bubble.artifacts {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
}

bubble-popover.css:
/* Bubble Popover */
.bubble-popover {
    position: absolute;
    right: 70px;
    top: 50%;
    transform: translateY(-50%);
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 16px;
    min-width: 220px;
    box-shadow: var(--glass-shadow);
    opacity: 0;
    visibility: hidden;
    transition: all 0.3s ease;
}



.nav-bubble:hover .bubble-popover {
    opacity: 1;
    visibility: visible;
    transform: translateY(-50%) translateX(-8px);
}

popover-header.css:
.popover-header {
    font-size: 14px;
    font-weight: 600;
    color: var(--light-100);
    margin-bottom: 12px;
    display: flex;
    align-items: center;
    gap: 8px;
}

popover-action.css:
.popover-actions {
    display: flex;
    flex-direction: column;
    gap: 8px;
}



.popover-action {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    font-size: 13px;
    color: var(--light-300);
}



.popover-action:hover {
    background: var(--dark-600);
    color: var(--light-100);
}

popover-status.css:
.popover-status {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 11px;
    color: var(--light-400);
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid var(--glass-border);
}

projects.css:
.nav-bubble.projects {
    background: linear-gradient(135deg, var(--accent-green), var(--accent-cyan));
    color: white;
}

training.css:
.nav-bubble.training {
    background: linear-gradient(135deg, var(--accent-yellow), var(--accent-red));
    color: white;
}

git.css:
.nav-bubble.git {
    background: linear-gradient(135deg, var(--accent-purple), var(--accent-blue));
    color: white;
}

research.css:
.nav-bubble.research {
    background: linear-gradient(135deg, var(--accent-cyan), var(--accent-green));
    color: white;
}

main-action.css:
/* Main Action Button */
.main-action {
    position: fixed;
    bottom: 100px;
    right: 24px;
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    border: none;
    color: white;
    font-size: 24px;
    cursor: pointer;
    transition: all 0.3s ease;
    box-shadow: 0 8px 32px rgba(59, 130, 246, 0.4);
    z-index: 1001;
}



.main-action:hover {
    transform: scale(1.1) rotate(90deg);
    box-shadow: 0 12px 48px rgba(59, 130, 246, 0.6);
}



    .main-action {
        right: 16px;
        bottom: 80px;
        width: 56px;
        height: 56px;
        font-size: 20px;
    }

chat-input-container.css:
/* Modern Input Area */
.chat-input-container {
    padding: 24px;
    background: var(--glass-bg);
    backdrop-filter: blur(20px);
    border-top: 1px solid var(--glass-border);
}



    .chat-input-container {
        padding: 16px;
    }

action-buttons.css:
/* Action Buttons Row */
.action-buttons {
    display: flex;
    gap: 12px;
    margin-bottom: 16px;
    flex-wrap: wrap;
}



    .action-buttons {
        flex-wrap: wrap;
        gap: 8px;
    }

action-btn.css:
.action-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--dark-700);
    border: 1px solid var(--glass-border);
    border-radius: 12px;
    padding: 10px 16px;
    color: var(--light-300);
    cursor: pointer;
    transition: all 0.3s ease;
    font-size: 13px;
    font-weight: 500;
}



.action-btn:hover {
    background: var(--dark-600);
    border-color: var(--accent-blue);
    color: var(--light-100);
    transform: translateY(-1px);
}



.action-btn.active {
    background: var(--accent-blue);
    border-color: var(--accent-blue);
    color: white;
}

chat-input-area.css:
/* Main Input Area */
.chat-input-area {
    display: flex;
    align-items: flex-end;
    gap: 12px;
    background: var(--dark-800);
    border: 1px solid var(--glass-border);
    border-radius: 20px;
    padding: 16px;
    transition: all 0.3s ease;
}



.chat-input-area:focus-within {
    border-color: var(--accent-blue);
    box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.1);
}

input-field.css:
.input-field {
    flex: 1;
    background: transparent;
    border: none;
    color: var(--light-100);
    font-size: 16px;
    line-height: 1.5;
    resize: none;
    min-height: 24px;
    max-height: 120px;
    outline: none;
    font-family: inherit;
}



.input-field::placeholder {
    color: var(--light-400);
}

quick-action.css:
.quick-actions {
    display: flex;
    gap: 8px;
    align-items: center;
}



.quick-action {
    width: 36px;
    height: 36px;
    border: none;
    background: var(--dark-700);
    color: var(--light-300);
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.3s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 14px;
}



.quick-action:hover {
    background: var(--dark-600);
    color: var(--accent-blue);
    transform: translateY(-1px);
}

send-button.css:
.send-button {
    background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
    color: white;
}



.send-button:hover {
    transform: translateY(-1px) scale(1.05);
    box-shadow: 0 4px 16px rgba(59, 130, 246, 0.4);
}
